import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Source Code Overview","description":"clice is a C++ language server designed from the architecture up around problems earlier servers could not solve without a redesign…","frontmatter":{"head":[["meta",{"property":"og:title","content":"Source Code Overview | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/overview"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/overview"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/overview"}],["meta",{"property":"og:description","content":"clice is a C++ language server designed from the architecture up around problems earlier servers could not solve without a redesign…"}]]},"headers":[],"relativePath":"clice/design/overview.md","filePath":"en/clice/design/overview.md","lastUpdated":1794738697000}'),n={name:"clice/design/overview.md"};function r(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="source-code-overview" tabindex="-1">Source Code Overview <a class="header-anchor" href="#source-code-overview" aria-label="Permalink to &quot;Source Code Overview&quot;">​</a></h1><p>clice is a C++ language server designed from the architecture up around problems earlier servers could not solve without a redesign:</p><ul><li><strong>Compilation context.</strong> Every step of compiling, indexing and answering knows which context a file compiles in — which command, which includer for a header — and the user can see and switch it. See <a href="./compilation-context">Compilation Context</a>.</li><li><strong>Multiple processes.</strong> A master process holds the state; worker processes run Clang, so a crash or a leak in Clang costs a worker, never the server. See <a href="./multi-process">Multi-process Architecture</a>.</li><li><strong>One build graph.</strong> Every expensive product — a preamble&#39;s PCH, a module&#39;s PCM, an open file&#39;s AST, a unit&#39;s compile for its index — is a node of one graph that shares builds, cancels them and invalidates them along their dependencies. See <a href="./task-graph">Compile Task Graph</a>.</li><li><strong>Coroutines.</strong> Asynchronous work is written as C++20 coroutines on the kotatsu library instead of callbacks.</li></ul><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><p><code>src/</code> is one C++20 module in layers, listed here from the bottom up: each imports only the layers listed before it, except that <code>server</code> and <code>analysis</code> sit side by side above <code>project</code>, and <code>analysis</code> imports no <code>worker</code>.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it holds</th></tr></thead><tbody><tr><td><code>support</code></td><td>Utilities: logging, JSON, text, fuzzy matching, markup, failure records.</td></tr><tr><td><code>vfs</code></td><td>clice&#39;s view of the disk: one identity per file however a path spells it, one freshness check (a stat, then a content hash) shared by everything that asks whether a file changed, and the on-disk cache store.</td></tr><tr><td><code>command</code></td><td>Compile commands: parsed once from the compilation databases, edited by the rules, completed by asking each command&#39;s compiler. See <a href="./command-resolve">Command Resolution</a>.</td></tr><tr><td><code>syntax</code></td><td>What needs no AST: the lexer, the include and module dependency scan, the dependency graph, include resolution. See <a href="./dependency-scanning">Dependency Scanning</a>.</td></tr><tr><td><code>compile</code></td><td>Clang behind one interface: a compilation&#39;s AST, diagnostics, tokens and directives, and clang-tidy.</td></tr><tr><td><code>semantic</code></td><td>Analysis over the AST: one traversal per compilation that every feature queries, symbol identities equal across units, the <a href="./template-resolver">template resolver</a>, documentation comments.</td></tr><tr><td><code>index</code></td><td>The symbol index: a unit&#39;s index, the per-file shards, the project index and its database, and the queries over all of them. See <a href="./symbol-index">Symbol Index</a>.</td></tr><tr><td><code>feature</code></td><td>Each language feature&#39;s answer, computed from an AST, the index or a document&#39;s text, with no state of its own.</td></tr><tr><td><code>settings</code></td><td><code>clice.toml</code> and the editor&#39;s settings over it, and the rules deciding what applies to each file.</td></tr><tr><td><code>worker</code></td><td>The worker processes and their pool: placement, priorities, memory, crashes and deadlines.</td></tr><tr><td><code>project</code></td><td>A project as the disk describes it: its databases, members and commands, the build graph with its PCHs and modules, and its index. Unsaved buffers never change what a project says of the disk.</td></tr><tr><td><code>server</code></td><td>The language server: the open documents, which project serves each, what answers a request now, and the connection to the editor.</td></tr><tr><td><code>analysis</code></td><td>The analyses behind <code>clice analyze</code> and <code>clice modularize</code>.</td></tr><tr><td><code>driver</code></td><td>The <code>clice</code> binary&#39;s subcommands.</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command (structured compile commands)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>project (task graph: PCH / PCM / AST / unit nodes) ──→ worker (processes)</span></span>
<span class="line"><span>    ↓ products</span></span>
<span class="line"><span>compile (drives Clang compilation)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>semantic (semantic map) ──→ index (unit index / shards / project index)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>feature (answers)</span></span></code></pre></div><p>The server routes each request to the source that can answer it now — an up-to-date AST, or the index while the file compiles — gathers the feature&#39;s inputs and replies. Compilation is pulled by requests, never started by an edit alone (see <a href="./incremental-parse">Incremental Compilation</a>).</p>`,9)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
